is_credential_field(key) {
    credential_exact := {
        "password", "passwd", "passphrase", "pwd",
        "secret", "client_secret", "app_secret", "shared_secret",
        "api_key", "access_key", "private_key", "encryption_key", "signing_key",
        "auth_token", "access_token", "api_token", "bearer_token",
        "login_password", "bind_pw", "db_password",
        "database_password", "connection_password", "sql_password",
        "master_password", "root_password", "admin_password", "user_password"
    }
    lower(key) == credential_exact[_]
}

is_credential_field(key) {
    endswith(lower(key), "_password")
}

is_credential_field(key) {
    endswith(lower(key), "_passwd")
}

is_credential_field(key) {
    endswith(lower(key), "_secret")
}

is_credential_field(key) {
    endswith(lower(key), "_token")
}

is_auth_context_key(key, path) {
    lower(key) == "key"
    auth_terms := {"auth", "cred", "secret", "passw", "login"}
    ancestor := path[_]
    is_string(ancestor)
    contains(lower(ancestor), auth_terms[_])
}

is_hardcoded_value(value) {
    is_string(value)
    value != ""
    not contains(value, "{{")
    not startswith(value, "$(")
    not startswith(value, "${")
    not startswith(value, "$ANSIBLE_VAULT")
}

path_to_search_key(path) = search_key {
    parts := [s | p := path[_]; is_string(p); s := p]
    search_key := concat(".", parts)
}

CxPolicy[result] {
    document := input.document[i]
    walk(document, [path, value])
    count(path) > 0
    field_name := path[count(path) - 1]
    is_string(field_name)
    is_credential_field(field_name)
    is_hardcoded_value(value)

    result := {
        "documentId": document.id,
        "resourceType": "n/a",
        "resourceName": "n/a",
        "searchKey": path_to_search_key(path),
        "issueType": "IncorrectValue",
        "keyExpectedValue": sprintf("'%s' should use a variable reference or vault secret instead of a hardcoded value", [field_name]),
        "keyActualValue": sprintf("'%s' contains a hardcoded credential value", [field_name]),
    }
}

